namespace ghidra.app.cmd.module;

using ghidra.framework.cmd;
using ghidra.program.model.listing;

/**
 * Delete a tree in the program.
 * 
 * 
 */
public class DeleteTreeCmd : Command<Program> {
	private string treeName;

	/**
	 * Constructor for DeleteTreeCmd.
	 * @param treeName name of tree to delete
	 */
	public DeleteTreeCmd(string treeName) {
		this.treeName = treeName;
	}

	/* @Override */
	public bool applyTo(Program program) {
		return program.getListing().removeTree(treeName);
	}

	/* @Override */
	public string getStatusMsg() {
		return null;
	}

	/* @Override */
	public string getName() {
		return "Delete " + treeName;
	}

}
